public fun IntArray.binarySearch(element: Int, fromIndex: Int = 0, toIndex: Int = size): Int {
    var low = fromIndex
    var high = toIndex - 1
    while (low <= high) {
        val mid = (low + high) ushr 1
        val v = this[mid]
        if (v < element) low = mid + 1 else if (v > element) high = mid - 1 else return mid
    }
    return -(low + 1)
}

