private fun DoubleArray.sortRange(from: Int, to: Int) {
    if (to - from < 2) return
    val tmp = DoubleArray(size)
    mergeSortDouble(this, tmp, from, to)
}

private fun mergeSortDouble(a: DoubleArray, tmp: DoubleArray, from: Int, to: Int) {
    if (to - from < 2) return
    if (to - from <= 7) {
        var i = from + 1
        while (i < to) {
            val x = a[i]
            var j = i - 1
            while (j >= from && a[j] > x) { a[j + 1] = a[j]; j-- }
            a[j + 1] = x
            i++
        }
        return
    }
    val mid = (from + to) ushr 1
    mergeSortDouble(a, tmp, from, mid)
    mergeSortDouble(a, tmp, mid, to)
    var i = from
    var j = mid
    var k = from
    while (i < mid && j < to) {
        if (a[j] < a[i]) { tmp[k++] = a[j++] } else { tmp[k++] = a[i++] }
    }
    while (i < mid) tmp[k++] = a[i++]
    while (j < to) tmp[k++] = a[j++]
    k = from
    while (k < to) { a[k] = tmp[k]; k++ }
}

