    val m = LinkedHashMap<K, MutableList<Boolean>>()
    for (e in this) {
        val k = keySelector(e)
        var l = m[k]
        if (l == null) { l = ArrayList<Boolean>(); m[k] = l }
        l.add(e)
    }
    return m
}
