public infix fun <R> BooleanArray.zip(other: Array<out R>): List<Pair<Boolean, R>> {
    val n = if (size < other.size) size else other.size
    val r = ArrayList<Pair<Boolean, R>>(n)
    var i = 0
    while (i < n) { r.add(Pair(this[i], other[i])); i++ }
    return r
}
